-- Phase A / 6 of 11: uploaded spreadsheet metadata (mirrors `UploadedFile`).
-- The mock stores metadata ONLY (no bytes). A row must never imply that file contents exist, so `storage_state`
-- stays 'metadata_only' until a real object has been written to the private bucket and verified.

create table public.uploaded_files (
  id uuid primary key default gen_random_uuid(),
  -- FILE-YYYY-NNNNN. Always generated by the trigger below.
  reference_no text not null unique,
  original_name text not null check (char_length(original_name) between 1 and 255 and original_name !~ '[/\\<>]'),
  file_type public.file_type not null,
  -- Same limit as validations/upload.ts (MAX_UPLOAD_MB = 10), and not empty.
  size_bytes bigint not null check (size_bytes > 0 and size_bytes <= 10485760),
  -- Location inside the PRIVATE `school-uploads` bucket. Internal: never shown to the public.
  storage_bucket text check (storage_bucket is null or storage_bucket = 'school-uploads'),
  storage_path text check (storage_path is null or (char_length(storage_path) <= 400 and storage_path ~ '^[A-Za-z0-9/_.-]+$' and storage_path !~ '\.\.' and storage_path !~ '^/')),
  storage_state text not null default 'metadata_only' check (storage_state in ('metadata_only', 'stored')),
  -- The public upload page collects no school, so both are optional (as in the existing model).
  school_id uuid references public.schools (id) on delete restrict,
  customer_name text check (customer_name is null or char_length(customer_name) <= 100),
  uploaded_at timestamptz not null default now(),
  constraint uploaded_files_state_consistent check (
    (storage_state = 'metadata_only' and storage_path is null and storage_bucket is null)
    or (storage_state = 'stored' and storage_path is not null and storage_bucket is not null)
  )
);
alter table public.uploaded_files enable row level security;
revoke all on table public.uploaded_files from anon, authenticated;

create index uploaded_files_uploaded_idx on public.uploaded_files (uploaded_at desc);
create index uploaded_files_school_idx on public.uploaded_files (school_id);
create index uploaded_files_type_idx on public.uploaded_files (file_type);
create index uploaded_files_name_trgm on public.uploaded_files using gin (original_name extensions.gin_trgm_ops);
create index uploaded_files_reference_trgm on public.uploaded_files using gin (reference_no extensions.gin_trgm_ops);

create function private.uploaded_files_before_insert()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  new.reference_no := private.format_reference('FILE', nextval('private.file_reference_seq'), 5);
  return new;
end;
$$;
revoke all on function private.uploaded_files_before_insert() from public;
create trigger uploaded_files_before_insert before insert on public.uploaded_files
  for each row execute function private.uploaded_files_before_insert();

-- No client role can insert rows (see 0008). Rows are written by a trusted server function using the service role
-- once the object exists in storage. Nothing here lets a client read or download a spreadsheet.
